CustomField.description:
Indicador visual del cobro:
- Blanco: Cuando no existe factura (añade el texto "Sin facturar");
- Amarillo: Cuando existe factura, no se ha cobrado, y la fecha ETD + Plazo de pago de la cuenta es mayor o igual al día en curso (añade el texto "Pendiente. Queda(n) x día(s)");
- Rojo: Cuando existe factura, no se ha cobrado, y la fecha ETD + Plazo de pago de la cuenta es menor al día en curso (añade el texto "Excedido por x día(s)");
- Verde: Cuando existe factura y se ha cobrado (añade el texto "Cobrado").

CustomField.formula:
IF ( ISBLANK ( Numero_de_Factura__c ) ,
IMAGE ( "/img/x.gif" , "Sin facturar" ) & " Sin facturar" ,

IF ( NOT ( ISBLANK ( Numero_de_Factura__c ) ) &&  ISPICKVAL ( FacturaClienteCobrada__c , "No" ) && ( ( ETD__c + VALUE ( TEXT ( Proforma__r.Cuenta__r.Parent.PlazoPago__c ) ) ) >= TODAY() ) ,
IMAGE ( "/img/samples/flag_yellow.gif" , "Pendiente" ) & " Pendiente. Queda(n) " & TEXT ( ( ETD__c + VALUE ( TEXT ( Proforma__r.Cuenta__r.Parent.PlazoPago__c ) ) ) - TODAY() ) & " día(s)",

IF ( NOT ( ISBLANK ( Numero_de_Factura__c ) ) &&  ISPICKVAL ( FacturaClienteCobrada__c , "No" ) && ( ( ETD__c + VALUE ( TEXT ( Proforma__r.Cuenta__r.Parent.PlazoPago__c ) ) ) < TODAY() ) ,
IMAGE ( "/img/samples/flag_red.gif" , "Excedido" ) & " Excedido por " & TEXT ( TODAY() - ( ETD__c + VALUE ( TEXT ( Proforma__r.Cuenta__r.Parent.PlazoPago__c ) ) ) ) & " día(s)" ,

IF ( NOT ( ISBLANK ( Numero_de_Factura__c ) ) &&  ISPICKVAL ( FacturaClienteCobrada__c , "Parcialmente" ) ,
IMAGE ( "/img/samples/flag_yellow.gif" , "Pendiente Cobro Parcial" ) & " Pendiente Cobro Parcial" ,

IF ( NOT ( ISBLANK ( Numero_de_Factura__c ) ) &&  ISPICKVAL ( FacturaClienteCobrada__c , "Sí" ) ,
IMAGE ( "/img/samples/flag_green.gif" , "Cobrado" ) & " Cobrado" ,

"No es posible definir el indicador"
)
)
)
)
)
